


noise2 = ""
 # getting characters except lowercase from noise2

lowercase = ''.join([ch for ch in noise2 if not ch.islower()])
print(lowercase)


numbers = ''.join([ch for ch in noise2 if ch.isdigit()])
print(numbers)

special_characters = ''.join([ch for ch in noise2 if not ch.isalnum()])
print(special_characters)


